def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: string representation of the time in 'HH:MM:SS' format
    :rtype: str
    """
    if not isinstance(value, time):
        raise TypeError("Expected a datetime.time object")

    return value.strftime('%H:%M:%S')

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance, got {}".format(type(value).__name__))

    try:
        return {
            'x': value.x,
            'y': value.y
        }
    except AttributeError as e:
        raise ValueError("Point instance is missing required attributes: {}".format(e))

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.record.keys())
    except AttributeError:
        raise ValueError("The object does not have a 'record' attribute or it is not a dictionary.")

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            if metadata is not None and not isinstance(metadata, dict):
                raise ValueError("Metadata must be a dictionary.")
            if timeout is not None and not (isinstance(timeout, (int, float)) and timeout >= 0):
                raise ValueError("Timeout must be a non-negative number or None.")
            try:
                return func(tx, *args, **kwargs)
            except Exception as e:
                raise RuntimeError(f"Transaction failed: {e}")
        wrapper._metadata = metadata
        wrapper._timeout = timeout
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key {key} not found in the list.")
    except AttributeError:
        raise TypeError("The method 'index' is not applicable to the current object type.")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self._data.values())
        else:
            result = []
            for key in keys:
                if isinstance(key, int):
                    result.append(self._data[list(self._data.keys())[key]])
                elif isinstance(key, str):
                    result.append(self._data[key])
                else:
                    raise ValueError(f"Invalid key type: {type(key)}. Expected int or str.")
            return result
    except (IndexError, KeyError) as e:
        raise KeyError(f"Key not found: {e}") from e
    except Exception as e:
        raise Exception(f"An error occurred: {e}") from e

def data(self, *keys):
    result = {}
    if not keys:
        return dict(zip(self._fields, self))
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields[key]] = self[key]
        elif isinstance(key, str):
            if key in self._fields:
                result[key] = getattr(self, key)
            else:
                result[key] = None
        else:
            raise TypeError(f"Invalid key type: {type(key)}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
            hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    try:
        if not isinstance(n, int) or n < -1:
            raise ValueError("n must be an integer greater than or equal to -1")
        if not isinstance(qid, int) or qid < -1:
            raise ValueError("qid must be an integer greater than or equal to -1")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary or None")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary or None")

        message = {
            "name": "DISCARD",
            "args": {
                "n": n,
                "qid": qid
            }
        }
        if dehydration_hooks:
            message["args"]["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks:
            message["args"]["hydration_hooks"] = hydration_hooks

        self.output_queue.append(message)
        return Response(handlers=handlers)
    except Exception as e:
        raise RuntimeError(f"Failed to append DISCARD message to output queue: {e}")

def round_half_to_even(n):
    try:
        # Convert input to float to handle numeric inputs
        n = float(n)
        # Use round with no decimal places specified to round half to even
        return round(n)
    except ValueError:
        # Raise an error if the input is not a valid number
        raise ValueError("Input must be a numeric value")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name:
        raise ValueError("Name must be a non-empty string.")
    if not isinstance(fields, dict):
        raise ValueError("Fields must be a dictionary.")
    if not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a dictionary.")

    class Point:
        def __init__(self, **kwargs):
            for field, field_type in fields.items():
                if field not in kwargs:
                    raise ValueError(f"Missing required field: {field}")
                if not isinstance(kwargs[field], field_type):
                    raise ValueError(f"Field {field} must be of type {field_type.__name__}")
                setattr(self, field, kwargs[field])
            self.srid = srid_map.get('srid', None)

        def __repr__(self):
            field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values}, srid={self.srid!r})"

    Point.__name__ = name
    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import lru_cache as _lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not hasattr(self, '_order'):
        raise AttributeError("This method requires the object to have an '_order' attribute.")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop(0)
    value = self.pop(key)
    return key, value

def setdefault(self, key, default=None):
    try:
        if key not in self:
            self[key] = default
        return self[key]
    except Exception as e:
        raise KeyError(f"An error occurred while setting default for key: {key}") from e

def get(self, key, default=None):
    try:
        return self[key]
    except KeyError:
        return default

