def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    try:
        if not isinstance(xmls, list) or not isinstance(files, list):
            raise ValueError("Both xmls and files should be lists.")

        grouped_files = {}
        for xml in xmls:
            if not isinstance(xml, str):
                raise ValueError("Each XML filename should be a string.")
            xml_basename = xml.split('.')[0]
            grouped_files[xml_basename] = []

        for file in files:
            if not isinstance(file, str):
                raise ValueError("Each file should be a string.")
            file_basename = file.split('.')[0]
            for xml_basename in grouped_files:
                if file_basename == xml_basename:
                    grouped_files[xml_basename].append(file)

        return grouped_files

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

