def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")

        number = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid frequency format: {frequency}") from e

def make_find_paths(find_paths):
    def is_pattern(s):
        return '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        if not is_pattern(path) and ':' not in path:
            # Transform path fragment into a glob pattern
            transformed_path = f'sh:**/*{path}*/**'
        else:
            # Pass through existing patterns or paths with colon untouched
            transformed_path = path
        transformed_paths.append(transformed_path)
    return transformed_paths

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or a list of strings representing the script.
    :param separator: A string used to separate commands in the one-liner.
    :return: A single string with the script commands separated by the separator.
    """
    if not script:
        raise ValueError("Script cannot be empty")

    if isinstance(script, str):
        script = script.splitlines()

    if not all(isinstance(line, str) for line in script):
        raise ValueError("All script lines must be strings")

    return separator.join(line.strip() for line in script if line.strip())

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("Arguments must be a list of strings.")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr, check=True)

        if verbose:
            print(f"Command output:\n{result.stdout}")

        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with error:\n{e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

