def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or recompute:
            self._scale = self._compute_scale()
        return self._scale
    elif isinstance(other, float):
        if self._scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        self._scale = other
    else:
        raise TypeError("other must be None or a float")

def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale

    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value.")

    if self._scale is None or self._scale == 0:
        raise LenaValueError("Graph has unknown or zero scale, cannot rescale.")

    scale_factor = other / self._scale
    self._scale = other

    # Assuming self._data is a list of tuples representing coordinates
    # and errors, and the last element of each tuple is the coordinate
    # to be rescaled.
    self._data = [(x[:-1] + (x[-1] * scale_factor,)) for x in self._data]

    return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 2 + (1 if isinstance(make_value(bin_), tuple) and len(make_value(bin_)) > 1 else 0):
        raise ValueError("Number of field_names must match the dimension of the result")

    graph_points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        elif get_coordinate == "middle":
            x = (bin_.left + bin_.right) / 2

        y_values = make_value(bin_.content)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point = {field_names[0]: x}
        for i, y in enumerate(y_values):
            point[field_names[i + 1]] = y

        graph_points.append(point)

    graph_scale = hist.scale if scale is True else scale

    return {"points": graph_points, "scale": graph_scale}

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, providedBy
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True, methods=True))
    required_attributes = set(iface.names(all=True, attributes=True)) - required_methods

    candidate_methods = set(dir(candidate))
    candidate_attributes = {name for name in candidate_methods if not callable(getattr(candidate, name))}

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    for method_name in required_methods.intersection(candidate_methods):
        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(f"Expected method {method_name} to be callable, but it is not")
            continue

        spec = inspect.getfullargspec(method)
        iface_method = iface.get(method_name)
        iface_spec = inspect.getfullargspec(iface_method)

        if spec.args != iface_spec.args:
            errors.append(f"Method {method_name} has incorrect signature: expected {iface_spec.args}, got {spec.args}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.verify import verifyClass
    from inspect import signature
    import zope.interface

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    # Check methods
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.method') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Not callable: {name}")
                else:
                    iface_method = iface[name]
                    try:
                        sig = signature(method)
                        iface_sig = signature(iface_method)
                        if not sig.parameters.keys() == iface_sig.parameters.keys():
                            errors.append(f"Method {name} has incorrect signature: {sig} != {iface_sig}")
                    except ValueError as e:
                        errors.append(f"Error checking signature for method {name}: {e}")

    # Check attributes
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.attribute') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class type")

    try:
        if tentative:
            return issubclass(candidate, iface)
        else:
            return all(hasattr(candidate, attr) for attr in dir(iface) if not attr.startswith('__'))
    except Exception as e:
        raise RuntimeError(f"An error occurred during verification: {e}")

def determineMetaclass(bases, explicit_mc=None):
    if not isinstance(bases, tuple):
        raise TypeError("bases must be a tuple")
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("explicit_mc must be a type or None")

    metaclasses = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError("All bases must be types")
        metaclass = type(base)
        if metaclass not in metaclasses:
            metaclasses.add(metaclass)

    if explicit_mc is not None:
        metaclasses.add(explicit_mc)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Find a common metaclass
    common_metaclass = None
    for m in metaclasses:
        if all(issubclass(c, m) for c in metaclasses):
            if common_metaclass is None or issubclass(m, common_metaclass):
                common_metaclass = m

    if common_metaclass is not None:
        return common_metaclass

    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not hasattr(self, '_order'):
        raise AttributeError("This method requires an '_order' attribute to track usage order.")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop()
    value = self.pop(key)
    return key, value

